using System.Text.Json; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Valora.Web.Services.Bff;
namespace Valora.Web.Controllers;
[Authorize,ApiController,AutoValidateAntiforgeryToken,Route("bff/workspace")]
public sealed class BffWorkspaceController(IBffApiClient api,BffAuthenticationService authentication):ControllerBase
{
 [AcceptVerbs("GET","POST","DELETE"),Route("{**resource}")] public async Task<IActionResult> Forward(string? resource,CancellationToken ct){var session=await authentication.GetAsync(HttpContext,ct);if(session is null)return Unauthorized(new{message="Sua sessão expirou. Entre novamente.",correlationId=HttpContext.TraceIdentifier});object? body=null;if(Request.ContentLength>0)body=await JsonSerializer.DeserializeAsync<JsonElement>(Request.Body,cancellationToken:ct);var correlation=Request.Headers["X-Correlation-Id"].FirstOrDefault()??HttpContext.TraceIdentifier;var path=resource?.StartsWith("search/global",StringComparison.OrdinalIgnoreCase)==true?$"/api/v1/{resource}":$"/api/v1/workspace/{resource}";if(string.IsNullOrEmpty(resource))path="/api/v1/workspace";try{using var response=await api.SendAsync(new HttpMethod(Request.Method),path+Request.QueryString,body,session.AccessToken,correlation,ct);var payload=await response.Content.ReadAsStringAsync(ct);Response.Headers["X-Correlation-Id"]=correlation;return new ContentResult{StatusCode=(int)response.StatusCode,ContentType="application/json",Content=payload};}catch(OperationCanceledException)when(!ct.IsCancellationRequested){return StatusCode(504,new{message="O Workspace está levando mais tempo que o esperado. Tente novamente em instantes.",correlationId=correlation});}catch(BffApiUnavailableException){return StatusCode(503,new{message="Não foi possível atualizar seu Workspace agora. Seus dados permanecem seguros.",correlationId=correlation});}}
}
